-- Set comment to table: "xrp_signer_list"
COMMENT ON TABLE "public"."xrp_signer_list" IS 'XRP signer list configuration for multi-signature accounts';
-- Set comment to column: "id" on table: "xrp_signer_list"
COMMENT ON COLUMN "public"."xrp_signer_list"."id" IS 'ID';
-- Set comment to column: "account_id" on table: "xrp_signer_list"
COMMENT ON COLUMN "public"."xrp_signer_list"."account_id" IS 'XRP account address (r...) that owns this signer list';
-- Set comment to column: "signer_quorum" on table: "xrp_signer_list"
COMMENT ON COLUMN "public"."xrp_signer_list"."signer_quorum" IS 'Minimum total weight of signatures required to authorize a transaction';
-- Set comment to column: "is_active" on table: "xrp_signer_list"
COMMENT ON COLUMN "public"."xrp_signer_list"."is_active" IS 'true: this signer list is currently active on the ledger';
-- Set comment to column: "set_tx_hash" on table: "xrp_signer_list"
COMMENT ON COLUMN "public"."xrp_signer_list"."set_tx_hash" IS 'Transaction hash of SignerListSet that created/updated this list';
-- Set comment to column: "created_at" on table: "xrp_signer_list"
COMMENT ON COLUMN "public"."xrp_signer_list"."created_at" IS 'creation date';
-- Set comment to column: "updated_at" on table: "xrp_signer_list"
COMMENT ON COLUMN "public"."xrp_signer_list"."updated_at" IS 'last update date';
-- Set comment to index: "idx_xrp_signer_list_account_active" on table: "xrp_signer_list"
COMMENT ON INDEX "public"."idx_xrp_signer_list_account_active" IS 'Only one active signer list per account';
